using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Drawing;
using System.Windows.Forms;
using Musikbox;
class AppPickerUiTests {
 static int count;static void Check(bool ok,string text){if(!ok)throw new Exception(text);count++;Console.WriteLine("OK "+text);}
 static IEnumerable<Control> All(Control parent){foreach(Control c in parent.Controls){yield return c;foreach(var child in All(c))yield return child;}}
 static void Shot(Form form,string path){using(var image=new Bitmap(form.Width,form.Height)){using(var graphics=Graphics.FromImage(image))graphics.CopyFromScreen(form.Location,Point.Empty,image.Size);image.Save(path);}}
 static void NewFolder(AppFolderDialog picker,string name){using(var timer=new Timer{Interval=20}){timer.Tick+=(s,e)=>{var dialog=Application.OpenForms.OfType<ModernForm>().FirstOrDefault(f=>f.Text=="Neuer Ordner");if(dialog==null)return;timer.Stop();All(dialog).OfType<TextBox>().Single().Text=name;((Button)dialog.AcceptButton).PerformClick();};timer.Start();All(picker).OfType<Button>().Single(b=>b.Text=="Neuer Ordner").PerformClick();}}
 static bool Overwrite(AppSaveFileDialog picker,bool yes){using(var timer=new Timer{Interval=20}){timer.Tick+=(s,e)=>{var confirm=Application.OpenForms.OfType<MessageView>().FirstOrDefault();if(confirm==null)return;timer.Stop();((Button)(yes?confirm.AcceptButton:confirm.CancelButton)).PerformClick();};timer.Start();return picker.AcceptSelection();}}
 [STAThread]static void Main(string[] args){string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);string child=Path.Combine(root,"Thema mit Leerzeichen");Directory.CreateDirectory(child);foreach(var file in new[]{"eins.mp3","zwei mit Leerzeichen.MP3","bild.jpg","ohneEndung","bestand.musikbox.json"})File.WriteAllText(Path.Combine(root,file),"unverändert");Application.EnableVisualStyles();
  using(var drives=new AppFolderDialog{StartAtDrives=true,InitialDirectory=root}){drives.Show();Application.DoEvents();Check(drives.CurrentDirectory==null&&drives.Address.Text=="Laufwerke","Import beginnt mit Laufwerken statt zuletzt verwendetem Ordner");Check(drives.Entries.Items.Count==DriveInfo.GetDrives().Length&&drives.Entries.Items.Cast<ListViewItem>().All(x=>x.SubItems[1].Text=="Laufwerk"),"Laufwerksübersicht enthält die verfügbaren Laufwerke");Check(!drives.AcceptSelection()&&drives.DialogResult!=DialogResult.OK,"Laufwerksübersicht selbst ist kein importierbarer Ordner");Check(drives.Navigate(child)&&drives.CurrentDirectory==child,"Aus Laufwerksübersicht kann in einen Ordner gewechselt werden");drives.ShowDrives();Check(drives.CurrentDirectory==null&&drives.NameInput.Text=="","Zurück zu Laufwerken verwirft die vorige Ordnerauswahl");drives.Close();}
  using(var drives=new AppOpenFileDialog{StartAtDrives=true,Multiselect=true,Filter="Musik|*.mp3"}){drives.Show();Application.DoEvents();Check(drives.CurrentDirectory==null,"Auch Titelimport startet bei Laufwerken");drives.Navigate(root);drives.NameInput.Text="eins.mp3";Check(drives.AcceptSelection()&&drives.FileName==Path.Combine(root,"eins.mp3"),"Titelwahl funktioniert nach der Laufwerksübersicht");drives.Close();}
  using(var open=new AppOpenFileDialog{InitialDirectory=root,Filter="Musik|*.mp3;*.flac|Alle Dateien|*.*",Multiselect=true}){open.Show();Application.DoEvents();Check(open.FormBorderStyle==FormBorderStyle.None&&open.Entries.BackColor==ModernTheme.Navy,"Dateiauswahl verwendet App-Rahmen und dunkelblaue Liste");Check(open.Entries.Items.Count==3&&open.Entries.Items.Cast<ListViewItem>().Any(x=>x.Text.EndsWith(".MP3")),"Dateifilter ignoriert Großschreibung und lässt Ordner sichtbar");Check(!open.Navigate(Path.Combine(root,"fehlt"))&&open.CurrentDirectory==root,"Nicht erreichbarer Ordner lässt die gültige Ansicht bestehen");open.NameInput.Text="fehlt.mp3";Check(!open.AcceptSelection()&&open.DialogResult!=DialogResult.OK,"Fehlende Quelldatei wird nicht übernommen");Shot(open,Path.Combine(root,"file-picker.png"));open.NameInput.Text="\"eins.mp3\" \"zwei mit Leerzeichen.MP3\"";Check(open.AcceptSelection()&&open.FileNames.Length==2&&open.FileNames.All(File.Exists),"Mehrfachauswahl verarbeitet Dateinamen mit Leerzeichen");open.Close();}
  using(var search=new AppOpenFileDialog{InitialDirectory=root,Filter="Musik|*.mp3"}){search.Show();Application.DoEvents();search.SearchInput.Text="ZWE leer";Check(search.Entries.Items.Count==1&&search.Entries.Items[0].Text=="zwei mit Leerzeichen.MP3","Namenssuche kombiniert Wortteile ohne Großschreibung");search.SearchInput.Text="";Check(search.Entries.Items.Count==3,"Leeres Suchfeld zeigt wieder alle passenden Einträge");search.Close();}
  using(var multi=new AppOpenFileDialog{InitialDirectory=root,Filter="Musik|*.mp3",Multiselect=true}){multi.Show();Application.DoEvents();foreach(ListViewItem item in multi.Entries.Items)if(item.Text.EndsWith("mp3",StringComparison.OrdinalIgnoreCase))item.Selected=true;Application.DoEvents();Check(multi.AcceptSelection()&&multi.FileNames.Length==2,"Mehrere direkt markierte Listeneinträge werden gemeinsam übernommen");multi.Close();}
  using(var open=new AppOpenFileDialog{InitialDirectory=root,Filter="Alle|*.*"}){open.Show();Application.DoEvents();Check(open.Entries.Items.Cast<ListViewItem>().Any(x=>x.Text=="ohneEndung"),"Alle-Dateien-Filter umfasst auch endungslose Dateien");open.NameInput.Text=child;Check(!open.AcceptSelection()&&open.CurrentDirectory==child,"Öffnen eines ausgewählten Ordners navigiert hinein");open.Close();}
  using(var open=new AppOpenFileDialog{InitialDirectory=root,Filter="Programm|MP3GAIN.EXE"}){Check(open.MatchesFilter("mp3gain.exe")&&!open.MatchesFilter("MP3GainGUI.exe"),"Programmfilter unterscheidet Kommandozeile und GUI-Datei");}
  using(var folders=new AppFolderDialog{SelectedPath=child}){folders.Show();Application.DoEvents();Check(folders.CurrentDirectory==child&&folders.Entries.Items.Count==0,"Ordnerwahl übernimmt den Ausgangspfad und zeigt keine Dateien");Check(folders.AcceptSelection()&&folders.SelectedPath==child,"Aktueller Ordner kann bestätigt werden");folders.Close();}
  using(var folders=new AppFolderDialog{SelectedPath=root}){folders.Show();Application.DoEvents();NewFolder(folders,"Neu angelegt");Check(Directory.Exists(Path.Combine(root,"Neu angelegt"))&&folders.CurrentDirectory==Path.Combine(root,"Neu angelegt"),"Neuer Ordner wird erst nach bestätigter Namenseingabe angelegt");string current=folders.CurrentDirectory;NewFolder(folders,"..");Check(folders.CurrentDirectory==current&&folders.State.Text.Contains("Ungültiger"),"Neuer Ordner weist Pfadtraversierung ab");folders.Close();}
  using(var save=new AppSaveFileDialog{InitialDirectory=root,Filter="Projekt|*.musikbox.json",FileName="Neues Projekt"}){save.Show();Application.DoEvents();Check(save.NameInput.Text=="Neues Projekt","Speichern erhält den vorgeschlagenen Namen");Check(save.Navigate(child)&&save.NameInput.Text=="Neues Projekt","Ordnerwechsel erhält den eingegebenen Speichernamen");Check(save.AcceptSelection()&&save.FileName==Path.Combine(child,"Neues Projekt.musikbox.json"),"Speichern ergänzt die vollständige Projektendung");Check(!File.Exists(save.FileName),"Auswahldialog selbst schreibt keine Datei");save.Close();}
  using(var save=new AppSaveFileDialog{InitialDirectory=root,Filter="Projekt|*.musikbox.json"}){save.Show();Application.DoEvents();save.NameInput.Text="bestand.musikbox.json";Check(!Overwrite(save,false)&&save.DialogResult!=DialogResult.OK,"Nein bei Ersetzen beendet die Auswahl nicht");Check(File.ReadAllText(Path.Combine(root,"bestand.musikbox.json"))=="unverändert","Abgelehntes Ersetzen lässt vorhandene Datei unverändert");Check(Overwrite(save,true)&&save.FileName==Path.Combine(root,"bestand.musikbox.json"),"Erst Ja bestätigt einen vorhandenen Speicherpfad");save.Close();}
  using(var save=new AppSaveFileDialog{InitialDirectory=root,Filter="Projekt|*.musikbox.json"}){save.Show();Application.DoEvents();save.NameInput.Text="CON";Check(!save.AcceptSelection(),"Reservierte Windows-Dateinamen werden abgewiesen");save.NameInput.Text=Path.Combine(root,"fehlt","test.json");Check(!save.AcceptSelection(),"Nicht vorhandener Zielordner wird abgewiesen");((Button)save.CancelButton).PerformClick();Check(save.FileNames.Length==0,"Abbrechen liefert keine bestätigten Speicherdateien");save.Close();}
  using(var color=new AppColorDialog{Color=Color.FromArgb(120,20,40,60)}){color.Show();Application.DoEvents();Check(color.Alpha.Value==120&&color.Red.Value==20&&color.Hex.Text=="#7814283C","Farbwahl übernimmt Farbe einschließlich Deckkraft");Shot(color,Path.Combine(root,"color-picker.png"));color.Hex.Text="#12ABEF";Check(color.ApplyHex()&&color.Color==Color.FromArgb(255,18,171,239),"RGB-Hexfarbe wird korrekt übernommen");color.Hex.Text="#80123456";Check(color.ApplyHex()&&color.Color.A==128,"ARGB-Hexfarbe erhält die Transparenz");Color before=color.Color;color.Hex.Text="kein Farbwert";Check(!color.ApplyHex()&&color.Color==before,"Ungültige Hexeingabe verändert keine Farbe");All(color).OfType<ColorSwatch>().Single(s=>s.Value==Color.Red).PerformClick();Check(color.Color==Color.Red,"Palette übernimmt die angeklickte Farbe im gestalteten Dialog");color.Close();}
  using(var font=new AppFontDialog{Font=new Font(FontFamily.GenericSansSerif,18,FontStyle.Bold)}){font.Show();Application.DoEvents();Check(font.PointSize.Value==18&&font.Bold.Checked,"Schriftwahl übernimmt Größe und Fettdruck");Shot(font,Path.Combine(root,"font-picker.png"));font.PointSize.Value=24;Check(font.ApplyFont()&&font.Font.SizeInPoints==24&&font.Font.Bold,"Ausgewählte Schriftgröße und Stil bleiben erhalten");font.Family.Text="Nicht-installierte-Testschrift";Check(!font.ApplyFont(),"Ungültige Schriftfamilie wird nicht stillschweigend ersetzt");font.Close();}
  Check(File.ReadAllText(Path.Combine(root,"eins.mp3"))=="unverändert","Dialogprüfungen verändern keine ausgewählten Quelldateien");Console.WriteLine("BESTANDEN: "+count+" eigene Auswahl-/Speicher-/Farb-/Schriftdialogprüfungen unter Mono");
 }
}
